class _AirtimePageState extends State<AirtimePage>{late bool data=widget.initialData;final phone=TextEditingController(text:'08012345678');final amount=TextEditingController(text:'200');String selected='Airtel';bool loading=false;Future<void> pay()async{setState(()=>loading=true);try{final r=await Api.servicePay(widget.user['user_id'], data?'Data - $selected':'Airtime - $selected', double.parse(amount.text), customer:phone.text); await widget.onDone(); if(!mounted)return; Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>SuccessPage(message:'${data?'Data':'Airtime'} Purchase Successful',balance:(r['balance'] as num).toDouble())));}catch(e){msg(context,e.toString());}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Airtime & Data')),body:ListView(padding:const EdgeInsets.all(16),children:[ToggleButtonsCustom(left:'Airtime',right:'Data',rightSelected:data,onChanged:(v)=>setState(()=>data=v)),const SizedBox(height:22),const Text('Select Operator',style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:12),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:['Airtel','MTN','Glo','9mobile'].map((o)=>ChoiceChip(label:Text(o),selected:selected==o,onSelected:(_)=>setState(()=>selected=o),selectedColor:C.red.withOpacity(.15))).toList()),const SizedBox(height:22),const Text('Phone Number',style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:8),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(suffixIcon:Icon(Icons.contact_phone_outlined))),const SizedBox(height:18),const Text('Amount',style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:8),Wrap(
  spacing: 8,
  children: [100, 200, 500, 1000]
      .map<Widget>(
        (a) => ChoiceChip(
          label: Text(
            '₹$a',
            style: TextStyle(
              color: amount.text == '$a'
                  ? Colors.white
                  : Colors.black,
            ),
          ),
          selected: amount.text == '$a',
          onSelected: (_) =>
              setState(() => amount.text = '$a'),
          selectedColor: C.red,
        ),
      )
      .toList(),
),const SizedBox(height:8),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(prefixText:'₹  ',hintText:'Enter amount')),const SizedBox(height:22),ElevatedButton(onPressed:loading?null:pay,child:Text(loading?'Please wait':'Continue'))]));}

class BillsPage extends StatefulWidget{final Map<String,dynamic> user;final Future<void> Function() onDone;final String? initial;const BillsPage({super.key,required this.user,required this.onDone,this.initial});@override State<BillsPage> createState()=>_BillsPageState();}
