class ToggleButtonsCustom extends StatelessWidget{final String left,right;final bool rightSelected;final ValueChanged<bool> onChanged;const ToggleButtonsCustom({super.key,required this.left,required this.right,required this.rightSelected,required this.onChanged});@override Widget build(BuildContext c)=>Container(height:44,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:Row(children:[Expanded(child:GestureDetector(onTap:()=>onChanged(false),child:Container(decoration:BoxDecoration(color:!rightSelected?C.red:Colors.transparent,borderRadius:BorderRadius.circular(18)),child:Center(child:Text(left,style:TextStyle(color:!rightSelected?Colors.white:Colors.black,fontWeight:FontWeight.w900)))))),Expanded(child:GestureDetector(onTap:()=>onChanged(true),child:Container(decoration:BoxDecoration(color:rightSelected?C.red:Colors.transparent,borderRadius:BorderRadius.circular(18)),child:Center(child:Text(right,style:TextStyle(color:rightSelected?Colors.white:Colors.black,fontWeight:FontWeight.w900))))))]));}

